gs={'Tpow':lambda p: T**p[0],'expT':lambda p: np.exp(-p[0]*T),'tanhT':lambda p: np.tanh(p[0]*T),'invT':lambda p: 1/(1+p[0]*T)}
fs={'eps^n exp(-k eps)':lambda p: eps**p[0]*np.exp(-p[1]*eps),'eps exp(-k eps^2)':lambda p: eps*np.exp(-p[1]*eps**2),'1-exp(-k eps)eps^n':lambda p: eps**p[0]*(1-np.exp(-p[1]*eps))}
hs={'eps2':lambda p: eps**2,'eps':lambda p: eps,'sqrt':lambda p: np.sqrt(eps),'expeps':lambda p: np.exp(-p[0]*eps)}
rng=np.random.default_rng(7)
out=[]
for (gn,g),(fn,f),(hn,h) in itertools.product(gs.items(),fs.items(),hs.items()):
