    nh=1 if hn=='expeps' else 0
    nf=2
    def model(p,g=g,f=f,h=h):
        a,b,c,d=p[0],p[1],p[2],p[3]
        pg=[p[4]]; pf=[p[5],p[6]]; ph=[p[7]]
        return a*np.tanh(b*T)+c*f(pf)*g(pg)+d*h(ph)
    best=None
    for _ in range(5):
        p0=rng.uniform(-2,2,8); p0[0]=rng.uniform(20,40); p0[1]=rng.uniform(0.3,0.6); p0[5]=abs(p0[5])+0.3; p0[6]=abs(p0[6])*0.3
